function Say($text, $color = "White") { Write-Host $text -ForegroundColor $color }

# ---------- 1. Project folder dhundho ----------
$Root = $PSScriptRoot
if (-not $Root) { $Root = (Get-Location).Path }

if (-not (Test-Path (Join-Path $Root "package.json"))) {
    $here = (Get-Location).Path
    if (Test-Path (Join-Path $here "package.json")) {
        $Root = $here
    } else {
        Say ""
        Say "GALTI: package.json nahi mila." Red
        Say "Is script ko apne 'crm' project folder (jisme package.json hai) me rakh kar chalayein." Yellow
        exit 1
    }
}

if (Test-Path (Join-Path $Root "src\app")) {
    $AppDir = Join-Path $Root "src\app"
} elseif (Test-Path (Join-Path $Root "app")) {
    $AppDir = Join-Path $Root "app"
} else {
    Say "GALTI: 'app' ya 'src\app' folder nahi mila. Kya yeh Next.js project hai?" Red
    exit 1
}


$Stamp = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"
$BackupDir = Join-Path $Root ("_backups\" + $Stamp)
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$Updated = @()
$Created = @()
$Skipped = @()

Say ""
Say "Project folder : $Root" Cyan
Say "App folder     : $AppDir" Cyan
Say ""

# ---------- 2. Helper: backup + write ----------
function Write-ProjectFile([string]$Target, [string]$Base64) {
    # [System.IO] use karte hain taaki [phone] / [slug] jaise folder naam theek se chalein
    $bytes = [Convert]::FromBase64String($Base64)
    $rel = $Target.Substring($Root.Length).TrimStart("\")

    if ([System.IO.File]::Exists($Target)) {
        $backupPath = Join-Path $BackupDir $rel
        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($backupPath))
        [System.IO.File]::Copy($Target, $backupPath, $true)
        $script:Updated += $rel
        Say "  UPDATE  $rel" Green
    } else {
        $script:Created += $rel
        Say "  NEW     $rel" Yellow
    }

    [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($Target))
    [System.IO.File]::WriteAllBytes($Target, $bytes)
}

# Sirf asli code folders me dhundho: app\ aur components\
# (backup / disabled / temp folders ko kabhi nahi chhedte)
function Find-ProjectFiles([string]$Name) {
    $searchRoots = @($AppDir)
    foreach ($c in @((Join-Path $Root "components"), (Join-Path $Root "src\components"))) {
        if ((Test-Path $c) -and ($searchRoots -notcontains $c)) { $searchRoots += $c }
    }
    $skipPattern = '\\(node_modules|\.next|_backups|\.git)\\|(?i)backup|disabled|[-_]temp|rider-step2-6-fix|live-source'
    $results = @()
    foreach ($r in $searchRoots) {
        $results += Get-ChildItem -LiteralPath $r -Recurse -File -Filter $Name -ErrorAction SilentlyContinue |
            Where-Object { $_.FullName.Substring($Root.Length) -notmatch $skipPattern }
    }
    return $results
}

# ---------- 3. API routes (fixed jagah) ----------
Say "API files:" White
Write-ProjectFile (Join-Path $AppDir "api\processing\orders\route.ts") ($B64_PROCESSING_ROUTE -join "")
Write-ProjectFile (Join-Path $AppDir "api\rider-my-tasks\route.ts")    ($B64_RIDER_TASKS -join "")
Write-ProjectFile (Join-Path $AppDir "api\rider-dashboard\route.ts")   ($B64_RIDER_DASH -join "")

# ---------- 4. Processing Dashboard panel ----------
Say ""
Say "Processing Dashboard panel (orders-panel.tsx) dhoondh rahe hain..." White
$panels = @(Find-ProjectFiles "orders-panel.tsx" | Where-Object {
    (Get-Content -LiteralPath $_.FullName -Raw) -match "/api/processing/orders"
})
if ($panels.Count -gt 0) {
    foreach ($p in $panels) { Write-ProjectFile $p.FullName ($B64_ORDERS_PANEL -join "") }
} else {
    $target = Join-Path $Root "components\orders-panel.tsx"
    Write-ProjectFile $target ($B64_ORDERS_PANEL -join "")
    Say "  DHYAN: purani orders-panel.tsx nahi mili, isliye nayi components\orders-panel.tsx banayi hai." Yellow
}

# ---------- 5. Rider OTP page ----------
Say ""
Say "Rider OTP page dhoondh rahe hain..." White
$otpPages = @(Find-ProjectFiles "page.tsx" | Where-Object {
    $c = Get-Content -LiteralPath $_.FullName -Raw
    ($c -match "/api/rider-start-delivery") -and ($c -match "verifyOtp")
})
if ($otpPages.Count -gt 0) {
    foreach ($p in $otpPages) { Write-ProjectFile $p.FullName ($B64_OTP_PAGE -join "") }
} else {
    $Skipped += "Rider OTP page (page.tsx) - project me nahi mila, kuch nahi badla"
    Say "  SKIP    Rider OTP page nahi mila - kuch nahi badla." DarkYellow
}

# ---------- 5b. ADMIN DASHBOARD: dummy data hata kar LIVE data ----------
Say ""
Say "Admin Dashboard (live data) set kar rahe hain..." White

# "@/..." alias kis folder ko point karta hai (src ya root)
$AliasBase = $Root
$tsconfigPath = Join-Path $Root "tsconfig.json"
if (Test-Path $tsconfigPath) {
    $tsconfig = Get-Content -LiteralPath $tsconfigPath -Raw
    if ($tsconfig -match '"@/\*"\s*:\s*\[\s*"(\./)?src/\*"') { $AliasBase = Join-Path $Root "src" }
} elseif ($AppDir -like "*\src\app") {
    $AliasBase = Join-Path $Root "src"
}

Write-ProjectFile (Join-Path $AppDir "api\admin\dashboard-live\route.ts") ($B64_DASH_API -join "")
Write-ProjectFile (Join-Path $AliasBase "components\admin\live-dashboard.tsx") ($B64_DASH_COMPONENT -join "")

# --- Sidebar ke links dhoondo, taaki dashboard ke buttons sahi page kholein ---
function Get-RoutePath([string]$PageFile) {
    $dir = Split-Path $PageFile
    $rel = $dir.Substring($AppDir.Length).Replace("\", "/")
    $parts = $rel.Split("/") | Where-Object { $_ -and -not ($_ -match '^\(.*\)$') }
    return "/" + ($parts -join "/")
}

$AllPages = @(Find-ProjectFiles "page.tsx") + @(Find-ProjectFiles "page.jsx") + @(Find-ProjectFiles "page.js") |
    Where-Object { $_.FullName.StartsWith($AppDir) }
$AllRoutes = @($AllPages | ForEach-Object { Get-RoutePath $_.FullName })

function Pick-Route([string[]]$Candidates) {
    foreach ($c in $Candidates) { if ($AllRoutes -contains $c) { return $c } }
    return $null
}

$ProcessingRoute = $null
foreach ($p in $AllPages) {
    $c = Get-Content -LiteralPath $p.FullName -Raw
    if ($c -match "orders-panel") { $ProcessingRoute = Get-RoutePath $p.FullName; break }
}
if (-not $ProcessingRoute) { $ProcessingRoute = Pick-Route @("/processing", "/admin/processing", "/processing/dashboard", "/processing/orders") }

$Links = [ordered]@{
    orders     = Pick-Route @("/admin/orders", "/orders")
    processing = $ProcessingRoute
    delivery   = Pick-Route @("/admin/delivery-control", "/admin/delivery", "/admin/delivery-dashboard", "/admin/delivery-control-tower", "/delivery-control")
    riders     = Pick-Route @("/admin/rider-approvals", "/admin/riders", "/admin/rider-list", "/admin/delivery-riders")
    inventory  = Pick-Route @("/admin/inventory", "/inventory")
    customers  = Pick-Route @("/admin/customers", "/customers")
}
$LinkLines = @()
foreach ($k in $Links.Keys) {
    if ($Links[$k]) { $LinkLines += "        ${k}: `"$($Links[$k])`"," ; Say ("  link    {0,-10} -> {1}" -f $k, $Links[$k]) Gray }
    else { $LinkLines += "        ${k}: null," }
}
$LinksBlock = $LinkLines -join "`r`n"

$WrapperPage = @"
import AdminLiveDashboard from "@/components/admin/live-dashboard";

// Fresh2Cook admin dashboard - live data from /api/admin/dashboard-live
export const dynamic = "force-dynamic";

export default function AdminDashboardPage() {
  return (
    <AdminLiveDashboard
      links={{
$LinksBlock
      }}
    />
  );
}
"@

$WrapperComponent = @"
import AdminLiveDashboard from "@/components/admin/live-dashboard";

// Fresh2Cook admin dashboard - live data from /api/admin/dashboard-live
// (purana dummy-data version _backups folder me hai)
export default function AdminDashboardContent(_props: Record<string, unknown>) {
  return (
    <AdminLiveDashboard
      links={{
$LinksBlock
      }}
    />
  );
}
"@

function Write-TextFile([string]$Target, [string]$Text) {
    Write-ProjectFile $Target ([Convert]::ToBase64String($Utf8NoBom.GetBytes($Text)))
}

$SidebarPattern = 'Manual Assignment|Rider Approvals|Admin Control Panel|OPERATIONS WORKSPACE|Operations Workspace'
$ShellImportPattern = '(?im)^\s*import[^;\n]*(Sidebar|AdminShell|AdminLayout|AppShell|SideNav|Navigation)[^;\n]*from'
$DummyPattern = 'Anita Sharma|New order received #10025|#10024 assigned to'

$AdminPage = $null
foreach ($n in @("page.tsx", "page.jsx", "page.js")) {
    $p = Join-Path $AppDir ("admin\" + $n)
    if (Test-Path $p) { $AdminPage = $p; break }
}

$DashboardDone = $false
$DashboardNote = ""

if ($AdminPage) {
    $pageText = Get-Content -LiteralPath $AdminPage -Raw
    $sidebarInPage = ($pageText -match $SidebarPattern) -or ($pageText -match $ShellImportPattern)

    if (-not $sidebarInPage) {
        # Sidebar layout me hai -> page.tsx ko seedha live dashboard se badal do
        $target = $AdminPage
        if ($AdminPage -notlike "*.tsx") {
            # page.js / page.jsx ko backup me le jao, nayi page.tsx banao
            $bk = Join-Path $BackupDir ($AdminPage.Substring($Root.Length).TrimStart("\"))
            New-Item -ItemType Directory -Force -Path (Split-Path $bk) | Out-Null
            Move-Item -LiteralPath $AdminPage -Destination $bk -Force
            $target = Join-Path $AppDir "admin\page.tsx"
        }
        Write-TextFile $target $WrapperPage
        $DashboardDone = $true
    } else {
        # Sidebar page ke andar hai -> sirf dummy data wali component file badlo (agar safe ho)
        $dummyFiles = @(
            @(Find-ProjectFiles "*.tsx") | Where-Object {
                $_.FullName -ne $AdminPage -and (Get-Content -LiteralPath $_.FullName -Raw) -match $DummyPattern
            }
        )
        foreach ($d in $dummyFiles) {
            $t = Get-Content -LiteralPath $d.FullName -Raw
            $exportCount = ([regex]::Matches($t, '(?m)^\s*export\s')).Count
            $hasDefault = $t -match '(?m)^\s*export\s+default'
            if ($hasDefault -and $exportCount -eq 1 -and -not ($t -match $SidebarPattern)) {
                Write-TextFile $d.FullName $WrapperComponent
                $DashboardDone = $true
            }
        }
    }
} else {
    $DashboardNote = "app\admin\page.tsx nahi mila"
}

if ($DashboardDone) {
    Say "  OK      Admin dashboard ab LIVE data dikhayega." Green
} else {
    # Safe tareeke se badal nahi sakte -> files ek zip me Desktop par rakh do
    $collect = @()
    if ($AdminPage) { $collect += $AdminPage }
    foreach ($n in @("layout.tsx", "layout.jsx", "layout.js")) {
        $l = Join-Path $AppDir ("admin\" + $n); if (Test-Path $l) { $collect += $l }
    }
    $collect += @(Find-ProjectFiles "*.tsx" | Where-Object { (Get-Content -LiteralPath $_.FullName -Raw) -match "$DummyPattern|$SidebarPattern" } | ForEach-Object { $_.FullName })
    $collect = @($collect | Select-Object -Unique | Select-Object -First 20)
    $desktop = [Environment]::GetFolderPath("Desktop")
    if (-not $desktop -or -not (Test-Path $desktop)) { $desktop = $Root }
    $zip = Join-Path $desktop "Fresh2Cook-admin-files.zip"
    if ($collect.Count -gt 0) {
        $tmpBase = $env:TEMP; if (-not $tmpBase) { $tmpBase = [IO.Path]::GetTempPath() }
        $tmp = Join-Path $tmpBase ("f2c-admin-" + $Stamp)
        New-Item -ItemType Directory -Force -Path $tmp | Out-Null
        foreach ($f in $collect) {
            $rel = $f.Substring($Root.Length).TrimStart("\")
            $dest = Join-Path $tmp $rel
            New-Item -ItemType Directory -Force -Path (Split-Path $dest) | Out-Null
            Copy-Item -LiteralPath $f -Destination $dest -Force
        }
        Compress-Archive -Path (Join-Path $tmp "*") -DestinationPath $zip -Force
    }
    $Skipped += "Admin dashboard page ko safe tareeke se nahi badal paye. $DashboardNote"
    Say "  RUKO    Admin page ka structure alag hai, isliye use nahi chheda." Yellow
    if ($collect.Count -gt 0) { Say "          Yeh file Claude ko bhejein:  $zip" Yellow }
}

# ---------- 5c. RIDER APP: sidebar + poori details ----------
Say ""
Say "Rider page (sidebar ke saath) bana rahe hain..." White

Write-ProjectFile (Join-Path $AppDir "api\rider-portal\route.ts") ($B64_RIDER_API -join "")
Write-ProjectFile (Join-Path $AliasBase "components\rider\rider-portal.tsx") ($B64_RIDER_COMPONENT -join "")

# Rider login page ka address dhoondo (logout / session khatam hone par wahan bhejenge)
$RiderLogin = $null
foreach ($p in $AllPages) {
    $c = Get-Content -LiteralPath $p.FullName -Raw
    if ($c -match "/api/rider-login") { $RiderLogin = Get-RoutePath $p.FullName; break }
}
if (-not $RiderLogin) { $RiderLogin = Pick-Route @("/rider/login", "/rider-login", "/delivery-login", "/rider") }
if (-not $RiderLogin) { $RiderLogin = "/rider/login" }
Say ("  link    rider login -> " + $RiderLogin) Gray

$RiderWrapper = @"
import RiderPortal from "@/components/rider/rider-portal";

// Fresh2Cook rider app - live data from /api/rider-portal
export const dynamic = "force-dynamic";

export default function RiderTasksPage() {
  return <RiderPortal loginPath="$RiderLogin" />;
}
"@

$riderTargets = @()
foreach ($p in $AllPages) {
    $route = Get-RoutePath $p.FullName
    if (@("/rider/my-tasks", "/rider/dashboard", "/rider-dashboard", "/rider/tasks") -contains $route) {
        $c = Get-Content -LiteralPath $p.FullName -Raw
        if (-not ($c -match "/api/rider-login")) { $riderTargets += $p.FullName }
    }
}

if ($riderTargets.Count -eq 0) {
    $riderTargets += (Join-Path $AppDir "rider\my-tasks\page.tsx")
}

foreach ($t in $riderTargets) {
    if ($t -notlike "*.tsx") {
        $bk = Join-Path $BackupDir ($t.Substring($Root.Length).TrimStart("\"))
        New-Item -ItemType Directory -Force -Path (Split-Path $bk) | Out-Null
        Move-Item -LiteralPath $t -Destination $bk -Force
        $t = [IO.Path]::ChangeExtension($t, ".tsx")
    }
    Write-TextFile $t $RiderWrapper
}
Say "  OK      Rider page ready:  localhost:3000/rider/my-tasks" Green

# ---------- 5d. RIDER PICKUP: Assignment ID ki jagah dropdown ----------
Say ""
Say "Rider Pickup page (dropdown) bana rahe hain..." White

Write-ProjectFile (Join-Path $AliasBase "components\rider\rider-pickup.tsx") ($B64_RIDER_PICKUP -join "")

$PickupWrapper = @"
import RiderPickup from "@/components/rider/rider-pickup";

// Fresh2Cook rider pickup - dropdown of orders ready for pickup
export const dynamic = "force-dynamic";

export default function RiderPickupPage() {
  return <RiderPickup loginPath="$RiderLogin" tasksPath="/rider/my-tasks" />;
}
"@

$pickupTargets = @()
foreach ($p in $AllPages) {
    $route = Get-RoutePath $p.FullName
    if (@("/rider/pickup-order", "/rider/pickup", "/rider-pickup") -contains $route) { $pickupTargets += $p.FullName }
}
if ($pickupTargets.Count -eq 0) { $pickupTargets += (Join-Path $AppDir "rider\pickup-order\page.tsx") }

foreach ($t in $pickupTargets) {
    if ($t -notlike "*.tsx") {
        $bk = Join-Path $BackupDir ($t.Substring($Root.Length).TrimStart("\"))
        New-Item -ItemType Directory -Force -Path (Split-Path $bk) | Out-Null
        Move-Item -LiteralPath $t -Destination $bk -Force
        $t = [IO.Path]::ChangeExtension($t, ".tsx")
    }
    Write-TextFile $t $PickupWrapper
}
Say "  OK      Pickup page ready:  localhost:3000/rider/pickup-order" Green

# ---------- 5e. v6: Settings, Admin OTP + All Pages, Customer account ----------
Say ""
Say "v7: Settings, Admin, Customer account, Home, Products, Policy pages..." White

foreach ($f in $V6Files) {
    $rel = $f.Path
    if ($rel.StartsWith("app\")) { $target = Join-Path $AppDir $rel.Substring(4) }
    else { $target = Join-Path $AliasBase $rel }
    Write-ProjectFile $target ($f.Data -join "")
}

# --- Database: nayi tables (AppSetting, CustomerAccount) ---
# Ab yeh tables app khud pehli baar use hone par bana leta hai (prisma generate ki zaroorat nahi).
# schema.prisma me models sirf record ke liye add kiye jaate hain.
$SchemaPath = Join-Path $Root "prisma\schema.prisma"
if (Test-Path $SchemaPath) {
    $schemaText = Get-Content -LiteralPath $SchemaPath -Raw
    if ($schemaText -notmatch "model\s+AppSetting\s*\{" -or $schemaText -notmatch "model\s+CustomerAccount\s*\{") {
        $bk = Join-Path $BackupDir "prisma\schema.prisma"
        New-Item -ItemType Directory -Force -Path (Split-Path $bk) | Out-Null
        Copy-Item -LiteralPath $SchemaPath -Destination $bk -Force
        $add = $Utf8NoBom.GetString([Convert]::FromBase64String(($B64_SCHEMA_ADD -join "")))
        [System.IO.File]::WriteAllText($SchemaPath, $schemaText.TrimEnd() + "`r`n" + $add, $Utf8NoBom)
        Say "  UPDATE  prisma\schema.prisma (AppSetting, CustomerAccount)" Green
    }
}
Say "  OK      Settings + Customer tables pehli baar page khulte hi apne aap ban jayengi" Green

# ---------- 6. Purana Next.js cache saaf ----------
$nextCache = Join-Path $Root ".next"
if (Test-Path $nextCache) {
    try {
        Remove-Item -LiteralPath $nextCache -Recurse -Force
        Say ""
        Say "Purana .next cache saaf kar diya." Gray
    } catch {
        Say ""
        Say "  .next cache saaf nahi hua (shayad server chal raha hai). Koi baat nahi." DarkYellow
    }
}

# ---------- 7. Summary ----------
Say ""
Say "==================== HO GAYA ====================" Green
Say ("Update hui files : " + $Updated.Count) Green
Say ("Nayi bani files  : " + $Created.Count) Yellow
if ($Skipped.Count -gt 0) { $Skipped | ForEach-Object { Say ("Skip             : " + $_) DarkYellow } }
if ($Updated.Count -gt 0) { Say ("Backup yahan hai : " + $BackupDir) Cyan }
Say ""
Say "Ab yeh karein:" White
Say "  1. Jis PowerShell/terminal me server chal raha hai, usme Ctrl + C dabayein." White
Say "  2. Phir chalayein:   npm run dev" White
Say "  3. Browser me localhost:3000/admin aur localhost:3000/rider/my-tasks, /rider/pickup-order kholein, Ctrl + F5 dabayein." White
Say "=================================================" Green
